package de.lowgiga.cuear;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.List;
public class ArDetailsStateTest {
 private GraphSnapshot graph(){return GraphSnapshot.parse("{\"version\":1,\"snapshotRevision\":\"r1\",\"title\":\"Local\",\"nodes\":[{\"id\":\"a\",\"label\":\"Alpha\",\"detail\":\"Saved detail\",\"x\":0,\"y\":0,\"z\":0},{\"id\":\"b\",\"label\":\"Beta\",\"x\":1,\"y\":0,\"z\":0},{\"id\":\"c\",\"label\":\"Gamma\",\"x\":0,\"y\":1,\"z\":0}],\"edges\":[{\"from\":0,\"to\":1},{\"from\":0,\"to\":1},{\"from\":2,\"to\":0}]}");}
 @Test public void startsClosedWithoutAnImplicitSelection(){ArDetailsState s=new ArDetailsState(graph());assertEquals(ArDetailsState.Panel.NONE,s.panel());assertNull(s.selectedNode());assertNull(s.selectedId());assertTrue(s.connections().isEmpty());}
 @Test public void invalidSelectionDoesNotChangeCurrentPanel(){ArDetailsState s=new ArDetailsState(graph());assertFalse(s.select(-1));assertFalse(s.select(3));assertEquals(ArDetailsState.Panel.NONE,s.panel());s.show(ArDetailsState.Panel.SETTINGS);assertFalse(s.select(999));assertEquals(ArDetailsState.Panel.SETTINGS,s.panel());}
 @Test public void aRealNodeOpensItsExactSnapshotDetails(){ArDetailsState s=new ArDetailsState(graph());assertTrue(s.select(0));assertEquals(ArDetailsState.Panel.DETAILS,s.panel());assertEquals("a",s.selectedId());assertEquals("Alpha",s.selectedNode().label);assertEquals("Saved detail",s.selectedNode().detail);}
 @Test public void backClosesThePanelBeforeRequestingAnyActivityExit(){ArDetailsState s=new ArDetailsState(graph());s.select(0);assertTrue(s.closePanel());assertEquals(ArDetailsState.Panel.NONE,s.panel());assertEquals("a",s.selectedId());assertFalse(s.closePanel());}
 @Test public void settingsAndInformationDoNotChangeNodeIdentity(){ArDetailsState s=new ArDetailsState(graph());s.select(1);s.show(ArDetailsState.Panel.SETTINGS);assertEquals("b",s.selectedId());s.show(ArDetailsState.Panel.INFO);assertEquals("b",s.selectedId());s.show(ArDetailsState.Panel.DETAILS);assertEquals("Beta",s.selectedNode().label);}
 @Test public void connectionsPreserveRealDirectionAndParallelEdgeCounts(){ArDetailsState s=new ArDetailsState(graph());s.select(0);List<ArDetailsState.Connection> c=s.connections();assertEquals(2,c.size());assertEquals(1,c.get(0).index);assertEquals(2,c.get(0).outgoing);assertEquals(0,c.get(0).incoming);assertEquals(2,c.get(1).index);assertEquals(1,c.get(1).incoming);assertEquals(0,c.get(1).outgoing);s.select(1);assertEquals(1,s.connections().size());assertEquals(2,s.connections().get(0).incoming);}
 @Test public void returnedConnectionListCannotMutateTheSnapshot(){ArDetailsState s=new ArDetailsState(graph());s.select(0);assertThrows(UnsupportedOperationException.class,()->s.connections().clear());assertEquals(3,graph().edges.size());}
 @Test public void detailPanelCannotOpenBeforeSelection(){ArDetailsState s=new ArDetailsState(graph());s.show(ArDetailsState.Panel.DETAILS);assertEquals(ArDetailsState.Panel.NONE,s.panel());s.show(ArDetailsState.Panel.SETTINGS);s.toggleSettings();assertEquals(ArDetailsState.Panel.NONE,s.panel());s.toggleSettings();assertEquals(ArDetailsState.Panel.SETTINGS,s.panel());}
}
